package br.com.onda;
import android.media.MediaExtractor;
import android.media.MediaFormat;
import java.io.*;
/** Validate actual tracks before preserving a direct file; never save a login HTML page as media. */
final class OriginalMedia {
 static void copy(File source,File target,String extension,DownloadMux.Cancel cancel)throws IOException{cancel.check();if(java.util.Arrays.asList("jpg","png","webp").contains(extension)){copyImage(source,target,extension,cancel);return;}MediaExtractor extractor=new MediaExtractor();boolean audio=false,video=false,mp3=false,aac=false;try{extractor.setDataSource(source.getPath());for(int i=0;i<extractor.getTrackCount();i++){String mime=extractor.getTrackFormat(i).getString(MediaFormat.KEY_MIME);audio|=mime!=null&&mime.startsWith("audio/");video|=mime!=null&&mime.startsWith("video/");mp3|="audio/mpeg".equals(mime);aac|="audio/mp4a-latm".equals(mime);}if(extension.equals("mp3")?!mp3:extension.equals("aac")?(!aac||video):extension.equals("m4a")?(!audio||video):!video)throw new IOException("O arquivo recebido não contém faixas compatíveis com "+extension.toUpperCase(java.util.Locale.ROOT)+".");}catch(RuntimeException e){throw new IOException("O servidor não entregou um arquivo de mídia válido.",e);}finally{extractor.release();}try(InputStream in=new FileInputStream(source);OutputStream out=new FileOutputStream(target)){byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1){cancel.check();out.write(buffer,0,n);}}cancel.check();}
 static void copyImage(File source,File target,String extension,DownloadMux.Cancel cancel)throws IOException{byte[] prefix=new byte[16];try(InputStream in=new FileInputStream(source)){int n=in.read(prefix);if(n<12||!extension.equals(TiktokPhotos.imageExtension(prefix)))throw new IOException("O servidor não entregou a imagem escolhida.");}android.graphics.BitmapFactory.Options bounds=new android.graphics.BitmapFactory.Options();bounds.inJustDecodeBounds=true;android.graphics.BitmapFactory.decodeFile(source.getPath(),bounds);if(bounds.outWidth<=0||bounds.outHeight<=0)throw new IOException("Imagem recebida inválida.");try(InputStream in=new FileInputStream(source);OutputStream out=new FileOutputStream(target)){byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1){cancel.check();out.write(buffer,0,n);}}cancel.check();}
}
